ruleContent.content:
@js:(function(){var J=Packages.org.jsoup.Jsoup;var MARK=/提供的《|\(第\d+/\d+页\)|^</div>|^&lt;\s*"https:/;function segs(h){var d=J.parse(h);var box=d.select('#content').first();if(box==null)return null;var c=box.clone();c.select('a,script,style').remove();var parts=String(c.html()).split(/<br\s*/?>/i),arr=[];for(var i=0;i<parts.length;i++){var t=parts[i].replace(/<[^>]+>/g,'').replace(/^[ 	
]+/,'').replace(/[ 	
]+$/,'');if(t.replace(/&nbsp;|&amp;|\s/g,'')==='')continue;if(MARK.test(t)&&arr.length>0)break;arr.push(t);}return {arr:arr,next:(box.select('a.btn-info').size()>0?box.select('a.btn-info').attr('href'):null)};}function isRepeat(page,out){if(out.length<3||page.length<2)return false;var p0=page[0];var lo=Math.max(0,out.length-60);for(var i=lo;i<out.length;i++){if(out[i]!==p0)continue;var ok=0;for(var j=0;j<page.length&&i+j<out.length;j++){if(out[i+j]!==page[j])break;ok++;}if(ok>=Math.min(3,page.length))return true;}return false;}var cur=segs(result),out=[],guard=0;while(cur!=null&&guard<40){guard++;var a=cur.arr;if(a.length>0&&!isRepeat(a,out)){if(out.length>0&&!/^&nbsp;/.test(a[0])){out[out.length-1]=out[out.length-1]+a[0];a=a.slice(1);}for(var i=0;i<a.length;i++)out.push(a[i]);}if(!cur.next)break;cur=segs(java.ajax(cur.next));}var txt=out.join('
').replace(/&(?:amp;)?n\s*bsp;/g,'&nbsp;');txt=txt.replace(/&nbsp;/g,' ').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&amp;/g,'&');var NOISE=/请牢记|免费最快|无防盗|恋上你看书|bookla|收藏本站|请收藏|请大家收藏|全网最快|更新速度|首发起点|支持正版|看清爽的小说就到|您现在阅读的是|天才一秒|记住本站|无弹窗|笔趣阁|最快更新|本章未完|点击下一页/;var DOM=/https?://|https?:\s*"|www\.|\.com|\.net|\.org|bookla|提供的《/;var ls=txt.split('
'),res=[];for(var k=0;k<ls.length;k++){var t=ls[k].replace(/^\s+|\s+$/g,'');if(!t)continue;t=t.replace(/[,，]\s*请牢记[:：]?.*$/,'').replace(/^\s+|\s+$/g,'');if(!t)continue;if(DOM.test(t)&&t.length<90)continue;if(t.length<=60&&NOISE.test(t))continue;res.push(t);}return res.join('
');})()

