@js:
java.toast("\n 正在进行发现页更新...");
let list = [];
const push = (title, url, size) => list.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});

const html = org.jsoup.Jsoup.parse(java.ajax(source.getKey()));
let items = html.select("ul.fenlei-item > a");
const reg = /^\/lists\/[0-9]+\.html$/;
// java.log(html);
for (let i = 0; i < items.size(); i++) {
    let a = items.get(i);

    let href = a.attr("href");
    if (reg.test(href)) {
        let title = a.text();
        push(title, href + `?page={{page}}`, 0.3);
    }   
}

java.toast("\n 发现页更新完成");
JSON.stringify(list);

