@js:
var base = baseUrl.replace(/&page=\d+/, '').replace(/\?page=\d+/, '');
var conn = base.indexOf('?') !== -1 ? '&' : '?';
var totalMatch = src.match(/共\s*(\d+)\s*页/);
var total = totalMatch ? parseInt(totalMatch[1]) : 42;
var result = [];
for (var p = 2; p <= total; p++) {
    result.push(base + conn + 'page=' + p);
}
result;

